"""Dependency-aware dispatch of voice event composition handlers."""

from __future__ import annotations

import asyncio
from dataclasses import dataclass
from graphlib import CycleError, TopologicalSorter
from typing import Any, Dict, Sequence, Set

import structlog

from rasa.core.voice.event_composition.events.input_events import InputEvent
from rasa.core.voice.event_composition.handlers.protocol import EventCompositionHandler

structlogger = structlog.get_logger()

Handler = EventCompositionHandler[Any]


@dataclass(eq=False)
class _HandlerNode:
    """Identity-based node wrapping a handler in the dependency graph."""

    handler: Handler


class HandlerOrchestrator:
    """Dispatch events through a non-circular handler dependency graph."""

    def __init__(self, handler_dependencies: Dict[Handler, Set[Handler]]) -> None:
        """Create an orchestrator and validate its dependency graph.

        Args:
            handler_dependencies: Maps each handler to the handlers that must
                finish before it runs.

        Raises:
            CycleError: If the handler dependency graph contains a cycle.
        """
        self._dependencies = self._create_dependency_graph(handler_dependencies)
        try:
            self._handler_order = tuple(
                TopologicalSorter(self._dependencies).static_order()
            )
        except CycleError:
            structlogger.error(
                "event_composer.circular_handler_dependencies",
                event_info="Handler dependencies must not contain a cycle.",
            )
            raise

    @property
    def handlers(self) -> Sequence[Handler]:
        """Return handlers in dependency-safe order."""
        return tuple(node.handler for node in self._handler_order)

    async def dispatch(self, event: InputEvent) -> None:
        """Dispatch an event after satisfying each handler's dependencies."""
        # Maps each handler node to its dependent handler tasks for the given event.
        tasks: Dict[_HandlerNode, asyncio.Task[None]] = {}

        for node in self._handler_order:
            # Tasks this handler must wait for before it's own handle() can run.
            dependency_tasks = [
                tasks[dependency] for dependency in self._dependencies[node]
            ]
            # Schedule immediately. The task blocks internally on its dependencies, so
            # independent handlers can run concurrently.
            tasks[node] = asyncio.create_task(
                self._dispatch_handler_after_dependencies(
                    node.handler,
                    event,
                    dependency_tasks,
                )
            )

        # Wait for the whole graph to drain before the next event is dispatched.
        await asyncio.gather(*tasks.values())

    @staticmethod
    def _create_dependency_graph(
        handler_dependencies: Dict[Handler, Set[Handler]],
    ) -> Dict[_HandlerNode, Set[_HandlerNode]]:
        """Wrap each handler in an identity node and rebuild the dependency graph.

        Wrapping each handler in an identity-based node (keyed by id()) guarantees every
        handler stays a unique node regardless of its own equality semantics.
        """
        nodes: Dict[int, _HandlerNode] = {
            id(handler): _HandlerNode(handler) for handler in handler_dependencies
        }
        return {
            nodes[id(handler)]: {nodes[id(dependency)] for dependency in dependencies}
            for handler, dependencies in handler_dependencies.items()
        }

    @staticmethod
    async def _dispatch_handler_after_dependencies(
        handler: Handler,
        event: InputEvent,
        dependency_tasks: Sequence[asyncio.Task[None]],
    ) -> None:
        """Run an interested handler after all its dependencies finish."""
        # Block until every dependency handler has finished its own handle() for this
        # event. If there are no dependencies this gather() returns instantly and the
        # handler falls straight through executing it's own handle() task.
        await asyncio.gather(*dependency_tasks)

        # Only hand the event to handlers that declared interest in its type.
        if isinstance(event, tuple(handler.interested_in)):
            await handler.handle(event)
